{"command": "cd /srv/analytics && .venv/bin/python -c "
import pyarrow.parquet as pq
import os
raw_dir = 'data/raw'
for f in sorted(os.listdir(raw_dir)):
    path = os.path.join(raw_dir, f)
    try:
        meta = pq.read_metadata(path)
        print(f'{f}: {meta.num_rows} rows, {meta.num_columns} cols, size={os.path.getsize(path)} bytes')
    except Exception as e:
        print(f'{f}: ERROR - {e}')
" 2>&1"}

